using Flagman;
public static class WorkflowBoundaryChecks
{
 static readonly DateTimeOffset Now=DateTimeOffset.Parse("2026-10-14T10:00:00Z");
 static readonly Actor Manager=new("m","manager"),Supplier=new("s","supplier"),Waiter=new("w","waiter");
 static State Fixture(){var s=new State();s.Users.Add(new("s","s","Supplier","supplier",true,"hash"));Inventory.AddProduct(s,new("p","Product","g"),Now);Inventory.SaveDish(s,new("d","Dish","Test",[new("p",500)]),Now);return s;}
 static void Stock(State s,decimal quantity=500)=>Inventory.Deliver(s,new("receipt",[new("p",quantity,"g",Now.AddHours(1))]),"receipt",Now);
 static void Error(Action a,int status){try{a();}catch(DomainException e){WorkflowChecks.Check(e.Status==status,$"Expected {status}, got {e.Status}");return;}throw new Exception("Expected failure "+status);}
 public static int Run(){int count=0;void Test(string n,Action a){a();Console.WriteLine("PASS "+n);count++;}
 Test("Procurement_line_validation_ownership_cancel_body_conflict",()=>{var s=Fixture();var p=WorkflowService.CreateProcurement(s,new("s",[new("a","p",10,"kg"),new("b","p",5,"kg")]),Manager,"p",Now);var response=new ProcurementResponseInput(1,[new("a",8,Now.AddDays(1),Reason:"Less"),new("b",0,Reason:"None")]);Error(()=>WorkflowService.RespondProcurement(s,p.Id,response,new("other","supplier"),"r",Now),404);Error(()=>WorkflowService.RespondProcurement(s,p.Id,response with{Items=[response.Items[0],response.Items[0]]},Supplier,"r",Now),400);Error(()=>WorkflowService.RespondProcurement(s,p.Id,response with{Items=[new("a",11,Now.AddDays(1)),response.Items[1]]},Supplier,"r",Now),400);Error(()=>WorkflowService.RespondProcurement(s,p.Id,response with{Items=[new("a",8),response.Items[1]]},Supplier,"r",Now),400);WorkflowChecks.Check(s.DeliveryRequests.Count==0&&s.Movements.Count==0,"Invalid response changed stock");var r=WorkflowService.RespondProcurement(s,p.Id,response,Supplier,"r",Now);Error(()=>WorkflowService.RespondProcurement(s,p.Id,response with{ExpectedVersion=2},Supplier,"r",Now),409);Error(()=>WorkflowService.CancelProcurement(s,p.Id,new(1),Manager,"c",Now),409);WorkflowChecks.Check(r.ProcurementRequest.Items[0].Quantity==10,"Request overwritten");var p2=WorkflowService.CreateProcurement(s,new("s",[new("a","p",1,"kg")]),Manager,"p2",Now);WorkflowService.CancelProcurement(s,p2.Id,new(1),Manager,"cancel",Now);Error(()=>WorkflowService.RespondProcurement(s,p2.Id,new(1,[new("a",0,Reason:"None")]),Supplier,"r2",Now),409);});
 Test("All_rejected_response_no_delivery",()=>{var s=Fixture();var p=WorkflowService.CreateProcurement(s,new("s",[new("a","p",1,"kg")]),Manager,"p",Now);Error(()=>WorkflowService.RespondProcurement(s,p.Id,new(1,[new("a",0)]),Supplier,"r",Now),400);var r=WorkflowService.RespondProcurement(s,p.Id,new(1,[new("a",0,Reason:"None")]),Supplier,"r",Now);WorkflowChecks.Check(r.DeliveryRequestId==null&&r.ProcurementRequest.Status=="rejected"&&s.Batches.Count==0,"Full rejection made receipt");});
 Test("Two_lots_late_acceptance_rejection_and_exact_expiry",()=>{var s=Fixture();var d=WorkflowService.SubmitDelivery(s,new("lots",[new("p",1,"kg",Now.AddHours(1)),new("p",2,"kg",Now.AddHours(3))]),Supplier,"d",Now);Error(()=>WorkflowService.AcceptDelivery(s,d.Id,new(1,[new(d.Items[0].Id,1),new(d.Items[1].Id,2)]),Manager,"a",Now.AddHours(1)),400);Error(()=>WorkflowService.AcceptDelivery(s,d.Id,new(1,[new(d.Items[0].Id,0,Reason:"Expired"),new(d.Items[1].Id,3)]),Manager,"a",Now.AddHours(1)),400);var accepted=WorkflowService.AcceptDelivery(s,d.Id,new(1,[new(d.Items[0].Id,0,Reason:"Expired"),new(d.Items[1].Id,2)]),Manager,"a",Now.AddHours(1));WorkflowChecks.Check(s.Batches.Single().ExpiresAt==Now.AddHours(3)&&s.Batches.Single().RemainingQuantity==2000&&accepted.Status=="partially_accepted","Late acceptance extended expiry");Error(()=>WorkflowService.AcceptDelivery(s,d.Id,new(1,[new(d.Items[0].Id,0,Reason:"Expired"),new(d.Items[1].Id,2)]),Manager,"another",Now),409);var other=WorkflowService.SubmitDelivery(s,new("reject",[new("p",1,"g",Now.AddHours(1))]),Supplier,"d2",Now);WorkflowService.AcceptDelivery(s,other.Id,new(1,[new(other.Items[0].Id,0,Reason:"Bad")]),Manager,"reject",Now);WorkflowChecks.Check(s.Deliveries.Count==1,"Reject created delivery");});
 Test("Manual_reject_recipe_change_archive_and_expired_shortage",()=>{var s=Fixture();Stock(s);var o=WorkflowService.SubmitOrder(s,new([new("d",1)]),Waiter,"o",Now);Error(()=>WorkflowService.DecideOrder(s,o.Id,new(1,"reject"),new("cook","cook"),"a",Now),400);s.Dishes[0]=s.Dishes[0] with{Ingredients=[new("p",400)]};Error(()=>WorkflowService.DecideOrder(s,o.Id,new(1,"accept"),new("cook","cook"),"a",Now),409);WorkflowChecks.Check(s.OrderRequests[0].Status=="submitted"&&s.Batches[0].RemainingQuantity==500,"Recipe change consumed");WorkflowService.DecideOrder(s,o.Id,new(1,"reject","Changed","other"),new("cook","cook"),"r",Now);WorkflowChecks.Check(s.Orders.Count==0&&s.Shortages.Count==0,"Manual rejection counted shortage");var o2=WorkflowService.SubmitOrder(s,new([new("d",1)]),Waiter,"o2",Now);var rejected=WorkflowService.DecideOrder(s,o2.Id,new(1,"accept"),new("cook","cook"),"a2",Now.AddHours(1));WorkflowChecks.Check(rejected.Status=="rejected"&&s.Batches[0].RemainingQuantity==500&&s.Movements.Count==1&&s.Shortages.Count==1,"Expiry shortage partial consumption");});
 Test("Concurrent_reserved_orders_acceptance_retry_restart",()=>{var path=Path.Combine(Path.GetTempPath(),"flagman-concurrent-"+Guid.NewGuid()+".db");var st=new Store(path);st.Write(s=>{var f=Fixture();s.Products=f.Products;s.Dishes=f.Dishes;Stock(s,1000);return 0;});var a=st.Write(s=>WorkflowService.SubmitOrder(s,new([new("d",1)]),Waiter,"o1",Now));var b=st.Write(s=>WorkflowService.SubmitOrder(s,new([new("d",1)]),new("w2","waiter"),"o2",Now));var results=new[]{a,b}.Select((o,i)=>Task.Run(()=>new Store(path).Write(s=>WorkflowService.DecideOrder(s,o.Id,new(1,"accept"),new("cook","cook"),"accept"+i,Now)))).ToArray();Task.WaitAll(results);WorkflowChecks.Check(results.All(t=>t.Result.Status=="ready"),"Concurrency accepted twice");new Store(path).Write(s=>WorkflowService.DecideOrder(s,a.Id,new(1,"accept"),new("cook","cook"),"accept0",Now));st.Read(s=>{WorkflowChecks.Check(s.Batches.Single().RemainingQuantity==0&&s.Movements.Count(m=>m.Kind=="order")==2,"Duplicate consumption");return 0;});st.VerifyIntegrity();});
 Test("Warning_expired_revision_stable_writeoff_author_and_legacy_status",()=>{var s=Fixture();Stock(s);var b=s.Batches.Single();Error(()=>Inventory.WriteOffExpired(s,b.Id,Manager,"w",Now),409);Inventory.Expire(s,Now);var rev=s.Revision;Inventory.Expire(s,Now.AddMinutes(1));WorkflowChecks.Check(s.Revision==rev,"Idle revision churn");Inventory.Expire(s,b.ExpiresAt);WorkflowChecks.Check(s.Revision>rev&&s.Batches.Single().RemainingQuantity==500&&Inventory.BatchStatus(s,b,b.ExpiresAt)=="expired","Expiry not signaled");Error(()=>Inventory.WriteOffExpired(s,b.Id,Waiter,"w",b.ExpiresAt),403);Inventory.WriteOffExpired(s,b.Id,Manager,"w",b.ExpiresAt);Error(()=>Inventory.WriteOffExpired(s,b.Id,Manager,"other",b.ExpiresAt),409);WorkflowChecks.Check(s.Movements.Last().ActorId==Manager.UserId&&s.Movements.Last().Reason=="expired","Missing writeoff author");s.Movements[^1]=s.Movements[^1] with{Kind="expiry"};WorkflowChecks.Check(Inventory.BatchStatus(s,s.Batches.Single(),Now)=="written_off","Legacy loss status");});
 Test("Show_hide_auto_archive_and_emphasis_never_overrides_stock",()=>{var s=Fixture();OfferPublication.Set(s,"d",new("show",true,"Note",0),Manager,Now);var offer=OfferPublication.Build(s,Now).Single();WorkflowChecks.Check(offer.AvailablePortions==0&&offer.Emphasized,"Emphasis changed stock");Error(()=>WorkflowService.SubmitOrder(s,new([new("d",1)]),Waiter,"o",Now),409);Stock(s);OfferPublication.Set(s,"d",new("hide",true,"",1),Manager,Now);WorkflowChecks.Check(OfferPublication.Build(s,Now).Count==0,"Hide ineffective");OfferPublication.Set(s,"d",new("auto",false,"",2),Manager,Now);WorkflowChecks.Check(OfferPublication.Build(s,Now).Count==1,"Auto reset did not restore automatic offer");Error(()=>OfferPublication.Set(s,"d",new("show",false,new string('x',241),3),Manager,Now),400);s.Dishes[0]=s.Dishes[0] with{Archived=true};WorkflowChecks.Check(OfferPublication.Build(s,Now).Count==0,"Archived published");});
 Test("Demo_history_explicit_writeoffs_preserve_audit",()=>{var s=new State();Demo.Seed(s,Now);var losses=s.Movements.Where(m=>m.Kind=="write_off").ToList();WorkflowChecks.Check(losses.Count>0&&losses.All(m=>s.Audit.Any(a=>a.Action=="batch.written-off"&&a.EntityId==m.BatchId&&a.SessionId==m.ActorId)),"Demo writeoff audit was discarded");});
 Test("Supplier_manufacture_and_shelf_metadata_survive_late_acceptance",()=>{var s=Fixture();var manufactured=Now.AddMinutes(-30);var d=WorkflowService.SubmitDelivery(s,new("manufactured",[new("p",1,"kg",ShelfLifeHours:2,ManufacturedAt:manufactured)]),Supplier,"mfg",Now);WorkflowChecks.Check(d.Items.Single().ManufacturedAt==manufactured&&d.Items.Single().ShelfLifeHours==2,"Supplier metadata lost");WorkflowService.AcceptDelivery(s,d.Id,new(1,[new(d.Items[0].Id,1)]),Manager,"mfg-accept",Now.AddHours(1));var batch=s.Batches.Single();WorkflowChecks.Check(batch.ManufacturedAt==manufactured&&batch.ShelfLifeHours==2&&batch.ExpiresAt==Now.AddMinutes(90),"Acceptance lost metadata or extended expiry");});
 Test("Concurrent_supplier_responses_and_delivery_decisions_finalize_once",()=>{var path=Path.Combine(Path.GetTempPath(),"flagman-document-race-"+Guid.NewGuid()+".db");var st=new Store(path);st.Write(s=>{var f=Fixture();s.Products=f.Products;s.Dishes=f.Dishes;s.Users=f.Users;return 0;});var p=st.Write(s=>WorkflowService.CreateProcurement(s,new("s",[new("t","p",1,"kg")]),Manager,"p",Now));var response=new ProcurementResponseInput(1,[new("t",1,Now.AddHours(2))]);var outcomes=Enumerable.Range(0,2).Select(i=>Task.Run(()=>{try{new Store(path).Write(s=>WorkflowService.RespondProcurement(s,p.Id,response,Supplier,"r"+i,Now));return 200;}catch(DomainException e){return e.Status;}})).ToArray();Task.WaitAll(outcomes);WorkflowChecks.Check(outcomes.Select(x=>x.Result).Order().SequenceEqual(new[]{200,409}),"Concurrent responses created duplicate delivery");var d=st.Read(s=>s.DeliveryRequests.Single());WorkflowChecks.Check(st.Read(s=>s.Batches.Count)==0,"Response moved stock");var acceptance=new DeliveryAcceptanceInput(1,[new(d.Items[0].Id,1)]);outcomes=Enumerable.Range(0,2).Select(i=>Task.Run(()=>{try{new Store(path).Write(s=>WorkflowService.AcceptDelivery(s,d.Id,acceptance,Manager,"a"+i,Now));return 200;}catch(DomainException e){return e.Status;}})).ToArray();Task.WaitAll(outcomes);WorkflowChecks.Check(outcomes.Select(x=>x.Result).Order().SequenceEqual(new[]{200,409}),"Concurrent acceptance finalized twice");WorkflowChecks.Check(st.Read(s=>s.Deliveries.Count==1&&s.Batches.Single().RemainingQuantity==1000&&s.Movements.Count==1),"Duplicate receipt");st.VerifyIntegrity();});
 Test("Expiry_status_lag_excludes_old_physical_expired_stock",()=>{var s=Fixture();Stock(s);Flagman.Monitor.RefreshExpiryStatus(s,Now.AddHours(1));var at=Now.AddDays(3).AddHours(1);Inventory.Deliver(s,new("late",[new("p",1,"g",at.AddMilliseconds(-500))]),"late",at.AddSeconds(-1));Flagman.Monitor.RefreshExpiryStatus(s,at);WorkflowChecks.Check(Math.Abs(Telemetry.LastExpiryLagMs-500)<0.001,"Old physical expiry inflated status lag");Flagman.Monitor.RefreshExpiryStatus(s,at.AddSeconds(1));WorkflowChecks.Check(Math.Abs(Telemetry.LastExpiryLagMs-500)<0.001&&s.Batches.Sum(b=>b.RemainingQuantity)==501&&s.Movements.Count==2,"Monitor changed stock or recorded old expiry again");});
 Test("Any_batch_writeoff_requires_reason_and_preserves_retry_after_restart",()=>{
  var path=Path.Combine(Path.GetTempPath(),"flagman-writeoff-"+Guid.NewGuid()+".db");var st=new Store(path);
  st.Write(s=>{var f=Fixture();s.Products=f.Products;s.Dishes=f.Dishes;Stock(s);return 0;});
  var id=st.Read(s=>s.Batches.Single().Id);
  foreach(var reason in new string?[]{null,"", "  ",new string('x',501)})Error(()=>st.Write(s=>Inventory.WriteOff(s,id,new(reason),Manager,"bad",Now)),400);
  Error(()=>st.Write(s=>Inventory.WriteOff(s,id,new("Порча"),Waiter,"denied",Now)),403);
  WorkflowChecks.Check(st.Read(s=>s.Batches.Single().RemainingQuantity)==500,"Invalid writeoff changed stock");
  var written=st.Write(s=>Inventory.WriteOff(s,id,new("  Повреждена упаковка  "),Manager,"write",Now));
  var restarted=new Store(path);
  WorkflowChecks.Check(restarted.Write(s=>Inventory.WriteOff(s,id,new("Повреждена упаковка"),Manager,"write",Now)).MovementId==written.MovementId,"Writeoff retry changed movement");
  Error(()=>restarted.Write(s=>Inventory.WriteOff(s,id,new("Другая причина"),Manager,"write",Now)),409);
  Error(()=>restarted.Write(s=>Inventory.WriteOff(s,id,new("Порча"),Manager,"other",Now)),409);
  restarted.Read(s=>{var m=s.Movements.Single(m=>m.Kind=="write_off");WorkflowChecks.Check(m.Reason=="Повреждена упаковка"&&m.ActorId==Manager.UserId&&m.Quantity==-500&&Inventory.BatchStatus(s,s.Batches.Single(),Now)=="written_off","Missing writeoff reason, author or quantity");return 0;});restarted.VerifyIntegrity();
 });
 Test("Writeoff_removes_unusable_reservation_without_consuming_other_stock",()=>{
  var s=Fixture();Stock(s);var order=WorkflowService.SubmitOrder(s,new([new("d",1)]),Waiter,"reserved",Now);var id=s.Batches.Single().Id;
  WorkflowChecks.Check(Inventory.Reserved(s).GetValueOrDefault(id)==500,"Order not reserved");
  Inventory.WriteOff(s,id,new("Порча"),Manager,"write",Now);
  WorkflowChecks.Check(Inventory.Reserved(s).GetValueOrDefault(id)==0&&s.OrderRequests.Single().Status=="submitted","Written off stock remains reserved");
  var result=WorkflowService.DecideOrder(s,order.Id,new(1,"accept"),new("cook","cook"),"ready",Now);
  WorkflowChecks.Check(result.Status=="rejected"&&s.Movements.Count(m=>m.Kind=="order")==0&&s.Batches.Single().RemainingQuantity==0,"Cook consumed written off stock");
 });
 return count;}
}
